import math

def search_dimension(b: int, k: int) -> float:
    return math.log(k) / math.log(b)

def dimension_table(b: int = 8) -> None:
    for k in range(1, b + 1):
        print(f'D({b},{k}) = {search_dimension(b, k):.4f}')

if __name__ == '__main__':
    dimension_table()

def subcritical_decay(b: int = 5, k: int = 3, dmax: int = 8) -> None:
    for d in range(1, dmax + 1):
        s, t = k ** d, b ** d
        print(f'd={d}: succ={s}, total={t}, frac={s / t:.6f}')

if __name__ == '__main__':
    subcritical_decay()

import math

def search_dimension(b: int, k: int) -> float:
    return math.log(k) / math.log(b)

def bridge_check(b: int = 7, k: int = 4) -> None:
    D = search_dimension(b, k)
    for d in (1, 3, 10, 50):
        ratio = math.log(k ** d) / math.log(b ** d)
        print(f'd={d}: H_S/H_T={ratio:.6f} matches D={D:.6f}? '
              f'{math.isclose(ratio, D)}')

if __name__ == '__main__':
    bridge_check()

