import math
from typing import Tuple

def classify(b: int, k: int) -> Tuple[str, float]:
    if k == b:
        return ('trivial', 1.0)
    if k == 1:
        return ('deterministic', 0.0)
    return ('subcritical', math.log(k) / math.log(b))

algorithms.pseudocode:
function FORECAST(b, k, d, budget):
    fraction = (k / b) ** d
    info     = d * (ln(b) - ln(k))
    feasible = fraction >= budget
    return (fraction, info, feasible)

function COMPOSE(b1,k1,d1, b2,k2,d2):
    total = b1^d1 * b2^d2
    succ  = k1^d1 * k2^d2
    assert succ <= total
    entropy = d1*ln(k1) + d2*ln(k2)
    return (total, succ, entropy)
